package kr.minecraft.survival.civic;

import java.nio.file.*;
import java.sql.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;
import kr.minecraft.survival.economy.domain.*;

class CivicStoreTest {
    @TempDir Path temp;final UUID owner=UUID.randomUUID(),buyer=UUID.randomUUID();
    StateStore open(){return new StateStore(temp.resolve("생활경제.db"));}
    void activate(StateStore db,CivicStore store,StateStore.Receipt receipt){db.complete(receipt.id(),()->store.completeInside(receipt));}
    @Test void schemaOneMigrationPreservesPrivateLandTrustJobAndOtherAddonTables()throws Exception{
        try(var db=open()){db.player(owner,"Owner");db.grantXp(owner,Rules.Job.MINER,100,"2026-11-11",1000);var land=db.reserveLand(owner,"world",-1,-1,3,250000);db.complete(land.id(),()->db.activateLandInside(land.id()));db.trust(owner,buyer,true);db.meta("kept.preference","off");db.execute("CREATE TABLE farm_saved(id TEXT,value TEXT)");db.execute("INSERT INTO farm_saved VALUES('five','preserve')");db.execute("DROP TABLE land_tags");db.execute("PRAGMA user_version=1");}
        try(var db=open()){new CivicStore(db);assertEquals(2,((Number)db.rows("PRAGMA user_version").getFirst().get("user_version")).intValue());assertEquals(1,db.lands(owner).size());assertTrue(db.trusted(owner.toString()).contains(buyer.toString()));assertEquals(100,db.progress(owner,Rules.Job.MINER).xp());assertEquals("off",db.meta("kept.preference"));assertEquals("preserve",db.rows("SELECT value FROM farm_saved").getFirst().get("value"));}
    }
    @Test void pendingTownBecomesReviewAcrossRestartAndDoesNotReplay(){String id;try(var db=open()){var store=new CivicStore(db);id=store.reserveTown(owner,"world",0,0,"서울마을",1000000,64).id();}try(var db=open()){var store=new CivicStore(db);assertEquals("REVIEW",db.receipt(id).state());assertTrue(db.unresolved(owner));assertEquals("RESERVED",db.land("world",0,0).state());assertEquals(1,store.plots().size());assertTrue(store.towns().isEmpty());assertThrows(StateStore.Denied.class,()->db.resolve(id,true,"operator"));db.resolveCivic(id,false,"operator",()->store.cancelInside(id));assertNull(db.land("world",0,0));assertTrue(store.plots().isEmpty());assertFalse(db.unresolved(owner));assertThrows(StateStore.Denied.class,()->db.resolveCivic(id,true,"operator",()->{}));}}
    @Test void rejectedPlotPurchaseCleansUpOnRestartWithoutDeletingExistingTitle(){String id;try(var db=open()){var store=new CivicStore(db);activate(db,store,store.reserveTown(owner,"world",0,0,"서울마을",0,64));var plot=store.plots().getFirst();store.setPlotPrice(owner,plot.id(),5000);id=store.reservePlotBuy(buyer,plot.id(),5000).id();db.reject(id,"wallet refused before cleanup");assertNotNull(db.land("world",0,0));}try(var db=open()){var store=new CivicStore(db);assertEquals("ACTIVE",db.land("world",0,0).state());assertEquals(owner.toString(),db.land("world",0,0).owner());assertEquals("ACTIVE",store.plots().getFirst().state());assertEquals(5000,store.plots().getFirst().price());assertEquals(0,store.credit(owner));}}
    @Test void manualCompletionOfPurchaseChangesTitleAndProceedsAtomically(){try(var db=open()){var store=new CivicStore(db);activate(db,store,store.reserveTown(owner,"world",0,0,"서울마을",0,64));var plot=store.plots().getFirst();store.setPlotPrice(owner,plot.id(),5000);var receipt=store.reservePlotBuy(buyer,plot.id(),5000);db.review(receipt.id(),"wallet outcome unknown");db.resolveCivic(receipt.id(),true,"operator",()->store.completeInside(receipt));assertEquals(buyer.toString(),db.land("world",0,0).owner());assertEquals(buyer.toString(),store.plot(plot.id()).owner());assertEquals(5000,store.credit(owner));assertEquals("DONE",db.receipt(receipt.id()).state());assertThrows(StateStore.Denied.class,()->db.resolveCivic(receipt.id(),true,"operator",()->store.completeInside(receipt)));assertEquals(5000,store.credit(owner));}}
    @Test void quotaAndUniqueTownNameFailuresDoNotLeaveReceipts(){try(var db=open()){var store=new CivicStore(db);activate(db,store,store.reserveTown(owner,"world",0,0,"서울마을",0,64));int count=db.rows("SELECT id FROM receipts").size();assertThrows(StateStore.Denied.class,()->store.reserveTown(buyer,"world",2,2,"서울마을",0,64));assertThrows(StateStore.Denied.class,()->store.reserveExpansion(owner,store.towns().getFirst().id(),"world",1,0,0,1));assertThrows(StateStore.Denied.class,()->store.reserveExpansion(owner,store.towns().getFirst().id(),"other",1,0,0,16));assertThrows(StateStore.Denied.class,()->store.reserveExpansion(owner,store.towns().getFirst().id(),"world",1,1,0,16));assertEquals(count,db.rows("SELECT id FROM receipts").size());}}
    @Test void listingLimitsAndRejectedReserveFreeSlot(){try(var db=open()){var store=new CivicStore(db);var receipt=store.reserveListing(owner,new byte[]{1},100,"STONE",1,1,1);assertThrows(StateStore.Denied.class,()->store.reserveListing(owner,new byte[]{2},100,"STONE",1,1,1));db.reject(receipt.id(),"inventory save failed");store.cleanupRejected(receipt.id());var retry=store.reserveListing(owner,new byte[]{3},100,"STONE",1,1,1);activate(db,store,retry);assertEquals(1,store.listings(null).size());assertArrayEquals(new byte[]{3},store.listings(null).getFirst().item());}}
    @Test void escrowSurvivesRestartAndManualCancelUnlocksOnlyOriginalItem(){String id,item;try(var db=open()){var store=new CivicStore(db);var r=store.reserveListing(owner,new byte[]{4,5},100,"STONE",1,20,500);activate(db,store,r);item=store.listings(null).getFirst().id();id=store.reserveItem(buyer,item,100,false).id();}try(var db=open()){var store=new CivicStore(db);assertTrue(store.listings(null).isEmpty());assertEquals("REVIEW",db.receipt(id).state());assertArrayEquals(new byte[]{4,5},store.listing(item).item());db.resolveCivic(id,false,"operator",()->store.cancelInside(id));assertEquals("ACTIVE",store.listing(item).state());assertEquals(0,store.credit(owner));assertFalse(db.unresolved(buyer));}}
    @Test void futureCivicSchemaIsRejectedWithoutMigration(){try(var db=open()){db.meta("civic.schema","99");assertThrows(StateStore.Denied.class,()->new CivicStore(db));assertEquals("99",db.meta("civic.schema"));}}
    @Test void invalidTownNamesCannotInjectFormattingOrCommands(){for(String name:List.of("a","§a마을","마을/명령","마을\n이름","아주아주아주아주아주아주아주아주긴마을"))assertThrows(StateStore.Denied.class,()->CivicStore.townName(name));assertEquals("서울 마을",CivicStore.townName(" 서울   마을 "));}
}
